SOURCE_CLAIM_JSON: {"title":"World Report 2023: Pakistan","publisher":"Human Rights Watch","publication_date":"2023","url":"https://www.hrw.org/world-report/2023/country-chapters/pakistan","claim":"Throughout 2022, the government continued to control media and curtail dissent; authorities harassed and at times detained journalists and other civil society members for criticizing officials and policies.","locator":"lines 68-76","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Year-end human-rights synthesis with direct coverage of 2022 conduct and concrete examples.","final_evidence_use":"final_evidence","period_fit":"Retrospective annual summary covering 2022 under Sharif.","ruler_attribution":"Attributable to the Sharif-led government, though individual arrests were usually carried out by police or regulators rather than the PM personally.","contrary_evidence":["Some cases were framed as law-enforcement or sedition enforcement, so this is evidence of suppression rather than proof of direct PM orders in each case."],"lenses":["3B.2","3B.8","3B.10"]}

SOURCE_CLAIM_JSON: {"title":"World Report 2023: Pakistan","publisher":"Human Rights Watch","publication_date":"2023","url":"https://www.hrw.org/world-report/2023/country-chapters/pakistan","claim":"Women, religious minorities, and transgender people continued to face violence, discrimination, and persecution, while authorities failed to provide adequate protection or hold perpetrators to account.","locator":"lines 69-71, 83-95, 115","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Year-end human-rights synthesis with multiple specific examples across vulnerable groups.","final_evidence_use":"final_evidence","period_fit":"Covers 2022 conditions under Sharif.","ruler_attribution":"This describes state protection failures under Sharif's government, but much of the violence was perpetrated by non-state actors or inherited institutions.","contrary_evidence":["The report does not show a single Sharif-directed campaign against these groups; it shows a failure to protect and remedy."],"lenses":["3B.1","3B.7","3B.10"]}

